/// Cutoff word of a frequency index (`0..=127`, nearest step).
pub(super) fn cutoff_word(index: f32) -> f32 {
    f32::from_bits(FREQ[(index.round() as i32).clamp(0, 127) as usize])
}

/// Resonance word of the Mid knob counts (`-60..=60`, nearest step).
pub(super) fn res_word(mid: f32) -> f32 {
    f32::from_bits(RES[((mid.round() as i32).clamp(-60, 60) + 60) as usize])
}

/// Stage gain word of the Mid knob counts (`-60..=60`, nearest step).
pub(super) fn gain_word(mid: f32) -> f32 {
    f32::from_bits(GAIN[((mid.round() as i32).clamp(-60, 60) + 60) as usize])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cutoff_words_rise_and_hit_the_captured_ends() {
        assert_eq!(FREQ[0], 0x3882_4000);
        assert_eq!(FREQ[127], 0x3f7f_fffe);
        assert!(FREQ
            .windows(2)
            .all(|w| f32::from_bits(w[0]) < f32::from_bits(w[1])));
    }

    #[test]
    fn resonance_and_gain_words_match_the_captured_points() {
        assert_eq!(RES[60], 0x3e35_04f0);
        assert_eq!(RES[0], 0x3f00_0000);
        assert_eq!(GAIN[60], 0x3efd_70a4);
        assert_eq!(GAIN[0], 0x3f00_0000);
    }

    #[test]
    fn lookups_round_and_clamp() {
        assert_eq!(cutoff_word(-5.0), f32::from_bits(FREQ[0]));
        assert_eq!(cutoff_word(500.0), f32::from_bits(FREQ[127]));
        assert_eq!(res_word(0.4), f32::from_bits(RES[60]));
        assert_eq!(gain_word(99.0), f32::from_bits(GAIN[120]));
    }
}
